| **指示期限** | **{{指示期限}}** |

---

尊敬的{{客户名称}}：

题述欧洲申请收到了欧洲专利局于{{发文日期}}发出的Summons to attend oral proceedings pursuant to Rule 115(1)EPC（口头审理通知书），详情请见附件。该OA指出可以和审查员进行最后的口审oral proceeding来争取题述欧洲申请，听训成功则可以授权。口审oral proceedings将于欧洲时间{{口审日期时间}}通过视频会议进行。递交Summons的书面答复需要提前，本次Rule 115(1) EPC的书面答复无需缴纳任何官费，且如需可以递交不止一次书面答复，但必须在期限**{{书面答复截止日期}}**之前提交书面答复。

我方合作律所表示针对题述申请，申请人可以准备一套主要权要修改和几套辅助权要修改答复审查员，如果审查员认可其中的任意一套权要修改将下发preliminary opinion告知申请人取消口审期限，直接下发授权意向通告；如审查员不同意修改，申请人将可以借助参加口头审理，和审查员进行视频会议沟通讨论。

若贵方需要我方准备答复意见并在答复期限内递交，请于{{指示期限}}前给予我方明确的书面指示。如贵方在收到我方汇报邮件后两周之内（即指示期限内）无明确指示，将默认由我方准备答复意见，期间我方分析师会直接与贵方沟通确认。

本次转达为平转官文，不包含我方对所述官文的任何分析意见且我方将不单独转达纸件。

如您对此案有流程方面的疑问，请联系{{联系人}}，电子邮件：{{联系人邮箱}}，手机：{{联系人手机}}。

对上述事宜倘有任何疑问，欢迎随时垂询。

谨致问候
{{签名品牌}}
', 'md', 1, '');
