| **完成期限** | **{{缴费截止日期}}** |
| **指示期限** | **{{指示期限}}** |

---

尊敬的{{客户名称}}：

题述欧洲申请收到了欧洲专利局于{{发文日期}}发出的部分补充检索报告（Partial Supplementary Search Report）及其引用文献，现随函附上该部分补充检索报告、引用文献及当前权要。

审查员在发明单一性（Unity of Invention）上认为该申请的权利要求包含了{{发明组数}}组发明。审查员仅针对第一组发明进行了检索，并提供了{{引用文献数}}篇现有技术。经外所转达，此检索为部分检索，没有对所有的权要进行检索。如果申请人希望审查员针对其余{{剩余组数}}组发明进行检索的话，需要在{{缴费截止日期}}（自2023年11月1日起欧洲专利局（EPO）已废除10天的路邮时间）前另交检索费，每组费用为{{每组检索费}}欧元。申请人也可以只选择其中一组发明进行检索，这样就只需交一笔检索费。

如果现阶段不检索其余{{剩余组数}}组发明的话，在本申请审查期间申请人不能针对未缴纳检索费的权要内容进行修改，审查员将出具仅涵盖先前检索的发明的正式检索报告。在这种情况下，与未检索的发明相关的主题在本申请的进一步审查期间不可用于修改权利要求(R.137(5) EPC)。请贵方在{{指示期限}}前做出书面指示。

本次转达为平转官文，不包含我方对所述官文的任何分析意见且我方将不再单独转达纸件。

如题述申请有任何进一步来自官方的消息，我们将随即通知贵方。

如您对此案有流程方面的疑问，请联系{{联系人}}，电子邮件：{{联系人邮箱}}，手机：{{联系人手机}}。

对上述事宜倘有任何疑问，欢迎随时垂询。

谨致问候
{{签名品牌}}
