题述欧洲申请于{{收文日期}}收到欧洲专利局发出的预授权通知（Decision to Grant），现随函附上欧洲专利局发出的通知文件。该官文指出欧洲专利局将于{{公告日期}}在专利期刊上公告本专利。自公告日起，题述申请有三个月的生效期，即**{{生效截止日期}}**，如贵司需要在更多欧洲国家进行生效，烦请贵司于{{生效指示期限}}前给予我方书面指示。

题述申请授权之后9个月内第三方可以对该授权专利提出异议，届时如发生，我方合作律所会告知我方。

**递交分案申请**
我方欧洲合作律所指出，题述欧洲申请可以递交分案，但需在授权公告日期之前，即**{{分案截止日期}}**前。如客户此前已有书面指示，在此说明客户指示内容及日期。

**缴纳生效国家年费**
