| **完成期限** | **1）{{截止日期}}（可延期至 {{延期后截止日期}}，需交延期费）<br>2）尽快** |
| **指示期限** | **{{指示期限}}** |

---

尊敬的{{客户名称}}：

题述美国申请收到了美国专利商标局（USPTO）于{{发文日期}}发出的{{官文英文名称}}，详情请见附件。该审查意见的答复期限为{{期限描述}}，即**{{截止日期}}**。该期限可延至{{延期描述}}，即**{{延期后截止日期}}**，但需要向USPTO交纳延期费。

请贵方尽快审阅附件中的官文。若贵方需要我方于期限内答复美国专利商标局，请于{{指示期限}}前给予我方明确的书面指示，以便我方准备答复意见并及时递交。

**信息披露声明（Information Disclosure Statement）**

根据美国专利法的规定，在专利申请过程中，发明人、申请人、及他们在美国专利商标局的代理人中任何一方知晓的与本案申请的可专利性有重要关联（material to patentability）的文献资料，必须以Information Disclosure Statement（IDS）的形式向美国专利商标局提交。IDS文件通常包括几个方面：

a) 发明人/申请人/代理人已知的相关文献；
b) 发明人/申请人/代理人对相关领域检索获得的文献（但发明人/申请人/代理人并没有义务去做检索）；
c) 如果有除美国之外的国家或地区的与本案申请相关的专利申请，相应专利局反馈给发明人/申请人的相关文献及审查意见。

如果存在上述文献，请贵司立即提供给我方，以便我方及时准备并向美国专利商标局提交IDS。

请注意，该强制性的披露义务一直持续到申请获批，专利授权为止。而且，根据申请在审查过程所处的阶段，递交IDS的时限会有不同，在有些情况下还可能产生官费。未能履行该强制性的披露义务（mandatory duty of disclosure）可能会被视为不正当行为（inequitable conduct），导致整份专利无效且不能执行。所以在专利授权前，如果发明人/申请人获悉上述文献，请立即通知我方。并发送到{{IDS邮箱}}邮箱，以便我方在递交美国非临时专利申请时一并向美国专利商标局提交IDS。

本次转达为平转官文，不包含我方对所述官文的任何分析意见且我方将不再单独转达纸件。

如您对此案有流程方面的疑问，请联系{{联系人}}，电子邮件：{{联系人邮箱}}，手机：{{联系人手机}}。

对上述事宜倘有任何疑问，欢迎随时垂询。

谨致问候
{{签名品牌}}
', 'md', 1, '');
